    }
    .pse-recipient-chip[draggable="true"] { cursor: grab; }
    .pse-recipient-chip.pse-recipient-dragging { opacity: .48; cursor: grabbing; }
    .pse-recipient-area.pse-recipient-drop-target {
      border-color: var(--pse-primary);
