    .pse-color-choice.active::after {
      content: '\2713';
      position: absolute;
      inset: 0;
      display: grid;
      place-items: center;
      color: #fff;
      font-size: 1rem;
      font-weight: 800;
      text-shadow: 0 1px 3px rgba(0, 0, 0, .85);
    }
    .pse-color-choice[data-light="1"].active::after {
      color: #172033;
