      /* PSE_MAILBOX_STARTUP_START */
      let mailboxStartupPromise = null;
      let applicationUpdateStartupScheduled = false;
      let applicationUpdateStartupPromise = null;

      function scheduleApplicationUpdateStartup() {
        if (applicationUpdateStartupScheduled) return;
        applicationUpdateStartupScheduled = true;
        window.setTimeout(() => {
          if (!state.mailboxStarted && $('.modal.show')) {
            applicationUpdateStartupScheduled = false;
            return;
          }
          showAppliedUpdateNotice();
          applicationUpdateStartupPromise = checkApplicationUpdate(false, true);
        }, 700);
      }

      async function startApplicationMailbox(hardRefresh = false) {
        if (mailboxStartupPromise) return mailboxStartupPromise;
        if (state.mailboxStarted && !hardRefresh) return;
        state.mailboxStarted = true;
        try {
          const url = new URL(location.href);
          if (url.searchParams.has('open_pse')) {
            url.searchParams.delete('open_pse');
            history.replaceState({}, '', url.pathname + url.search + url.hash);
          }
        } catch (ignore) {}
        $('#fileLaunchMailboxHint')?.classList.add('d-none');
        scheduleApplicationUpdateStartup();
        mailboxStartupPromise = (async () => {
          await loadFolders(true, true, hardRefresh);
          window.setTimeout(pollFolderStatus, 5000);
        })();
        try {
          await mailboxStartupPromise;
        } finally {
          mailboxStartupPromise = null;
        }
      }

      async function initialiseApplicationStartup() {
        // Restore sign-in launch handles and display the local file before any mail work.
        await fileLaunchReady;
        if (!state.mailboxStarted && window.pseFileLaunch?.isFileLaunch()) {
          $('#fileLaunchMailboxHint')?.classList.remove('d-none');
          $('#lastSyncStatus').textContent = 'Local file — mailbox sync paused';
          $('#foldersList').innerHTML = '<div class="pse-empty"><div>Choose Open mailbox to load your folders.</div></div>';
          $('#messagesList').innerHTML = '<div class="pse-empty"><div>Mailbox messages have not been loaded in this file window.</div></div>';
          return;
        }
        await startApplicationMailbox();
      }
      /* PSE_MAILBOX_STARTUP_END */

      /* PSE_FULLSCREEN_START */
      const fullscreenPreferenceKey = 'pse_fullscreen_preference_v1';
      let fullscreenPreference = readFullscreenPreference();
      let fullscreenBusy = false;
      let fullscreenError = '';
      let fullscreenStorageUnavailable = false;
      let fullscreenPromptShown = false;
      let fullscreenPromptChecking = false;
      let fullscreenPromptTimer = null;

      function readFullscreenPreference() {
        try {
          const saved = localStorage.getItem(fullscreenPreferenceKey);
          return saved === '1' ? true : (saved === '0' ? false : null);
        } catch (ignore) { return null; }
      }

      function fullscreenElement() {
        return document.fullscreenElement || document.webkitFullscreenElement || null;
      }

      function fullscreenAppMode() {
        return window.matchMedia('(display-mode: fullscreen)').matches;
      }

      function fullscreenSupported() {
        const root = document.documentElement;
        return Boolean((root.requestFullscreen && document.fullscreenEnabled !== false) ||
          (root.webkitRequestFullscreen && document.webkitFullscreenEnabled !== false));
      }

      function fullscreenMobileDevice() {
        return navigator.userAgentData?.mobile === true || /android|iphone|ipad|ipod/i.test(navigator.userAgent) ||
          (navigator.maxTouchPoints > 0 && window.matchMedia('(max-width: 900px)').matches);
      }

      function renderFullscreenControls() {
        const nativeActive = Boolean(fullscreenElement());
        const active = nativeActive || fullscreenAppMode();
        const supported = fullscreenSupported();
        const canToggle = nativeActive || (supported && !active);
        $('#preferFullscreen').checked = fullscreenPreference === true;
        $('#preferFullscreen').disabled = fullscreenBusy || (!supported && fullscreenPreference !== true);
        $('#settingsFullscreenToggle').disabled = fullscreenBusy || !canToggle;
        $('#settingsFullscreenToggle').textContent = active ? 'Exit full screen' : 'Enter full screen';
        $('#settingsFullscreenToggle').setAttribute('aria-pressed', String(active));
        $('#settingsFullscreenToggle').classList.toggle('active', active);
        const button = $('#toggleFullscreen');
        button.classList.toggle('d-none', !canToggle || (!nativeActive && fullscreenPreference !== true));
        button.disabled = fullscreenBusy;
        button.title = active ? 'Exit full screen' : 'Enter full screen';
        button.setAttribute('aria-label', button.title);
        button.setAttribute('aria-pressed', active ? 'true' : 'false');
        button.classList.toggle('active', active);
        button.querySelector('i').className = active ? 'fa-solid fa-compress' : 'fa-solid fa-expand';
        $('#acceptFullscreen').disabled = fullscreenBusy;
        $('#declineFullscreen').disabled = fullscreenBusy;
        $('#fullscreenSettingsStatus').textContent = fullscreenError || (fullscreenStorageUnavailable
          ? 'Browser storage is unavailable; your choice is remembered for this visit only.'
          : (active ? 'Full screen is active.' : (supported
            ? 'Full screen is available. You can also leave it with the browser’s Back or Escape action.'
            : 'Full screen is unavailable in this browser. Try installing PSE from the Install button.')));
        $('#fullscreenPromptError').textContent = fullscreenError;
        $('#fullscreenPromptError').classList.toggle('d-none', !fullscreenError);
      }

      function rememberFullscreenPreference(enabled) {
        fullscreenPreference = Boolean(enabled);
        try {
          localStorage.setItem(fullscreenPreferenceKey, fullscreenPreference ? '1' : '0');
          fullscreenStorageUnavailable = false;
        } catch (ignore) { fullscreenStorageUnavailable = true; }
        renderFullscreenControls();
      }

      async function changeFullscreen(enabled) {
        if (fullscreenBusy) return false;
        if ((enabled && (fullscreenElement() || fullscreenAppMode())) || (!enabled && !fullscreenElement())) {
          fullscreenError = '';
          renderFullscreenControls();
          return true;
        }
        const root = document.documentElement;
        const method = enabled ? ((document.fullscreenEnabled !== false && root.requestFullscreen) || root.webkitRequestFullscreen)
          : (document.exitFullscreen || document.webkitExitFullscreen);
        if (!method || (enabled && !fullscreenSupported())) {
          fullscreenError = 'Full screen is unavailable in this browser.';
          renderFullscreenControls();
          return false;
        }
        fullscreenBusy = true;
        fullscreenError = '';
        renderFullscreenControls();
        try {
          // Request directly from the click/change handler, before any await.
          const request = enabled && method === root.requestFullscreen
            ? method.call(root, {navigationUI: 'hide'}) : method.call(enabled ? root : document);
          await request;
          return true;
        } catch (error) {
          console.warn('Full screen request failed.', error);
          fullscreenError = 'Your browser could not change full screen. Try the full screen button again.';
          return false;
        } finally {
          fullscreenBusy = false;
          renderFullscreenControls();
        }
      }

      function scheduleFullscreenPrompt() {
        if (fullscreenPromptTimer !== null || fullscreenPromptShown || fullscreenPreference !== null ||
          !fullscreenMobileDevice() || !fullscreenSupported() || fullscreenAppMode()) return;
        fullscreenPromptTimer = window.setTimeout(maybePromptMobileFullscreen, 1000);
      }

      async function maybePromptMobileFullscreen() {
        fullscreenPromptTimer = null;
        if (fullscreenPromptChecking || fullscreenPromptShown || fullscreenPreference !== null) return;
        fullscreenPromptChecking = true;
        try {
          await fileLaunchReady;
          if (applicationUpdateStartupScheduled && !applicationUpdateStartupPromise) {
            scheduleFullscreenPrompt();
            return;
          }
          if (applicationUpdateStartupPromise) await applicationUpdateStartupPromise;
          if (fullscreenPreference !== null || !fullscreenMobileDevice() || !fullscreenSupported() || fullscreenElement() || fullscreenAppMode()) return;
          if (document.hidden || $('.modal.show') || Swal.isVisible?.()) {
            scheduleFullscreenPrompt();
            return;
          }
          fullscreenPromptShown = true;
          $('#fullscreenPrompt').classList.remove('d-none');
        } catch (error) {
          console.warn('Unable to prepare the full screen prompt.', error);
        } finally { fullscreenPromptChecking = false; }
      }

      $('#acceptFullscreen').addEventListener('click', () => {
        rememberFullscreenPreference(true);
        changeFullscreen(true).then(entered => {
          if (entered) $('#fullscreenPrompt').classList.add('d-none');
          else $('#declineFullscreen').textContent = 'Close';
        });
      });
      $('#declineFullscreen').addEventListener('click', () => {
        if (!fullscreenError) rememberFullscreenPreference(false);
        $('#fullscreenPrompt').classList.add('d-none');
      });
      $('#preferFullscreen').addEventListener('change', event => {
        rememberFullscreenPreference(event.target.checked);
        $('#fullscreenPrompt').classList.add('d-none');
        changeFullscreen(event.target.checked);
      });
      ['toggleFullscreen', 'settingsFullscreenToggle'].forEach(id => {
        $('#' + id).addEventListener('click', () => changeFullscreen(!fullscreenElement() && !fullscreenAppMode()));
      });
      ['fullscreenchange', 'webkitfullscreenchange'].forEach(name => document.addEventListener(name, renderFullscreenControls));
      document.addEventListener('hidden.bs.modal', scheduleFullscreenPrompt);
      document.addEventListener('visibilitychange', () => { if (!document.hidden) scheduleFullscreenPrompt(); });
      window.addEventListener('resize', scheduleFullscreenPrompt);
      window.addEventListener('storage', event => {
        if (event.key !== fullscreenPreferenceKey && event.key !== null) return;
        fullscreenPreference = readFullscreenPreference();
        renderFullscreenControls();
        scheduleFullscreenPrompt();
      });
      window.matchMedia('(display-mode: fullscreen)').addEventListener?.('change', renderFullscreenControls);
      renderFullscreenControls();
      scheduleFullscreenPrompt();
      /* PSE_FULLSCREEN_END */

      applySettingsToForm(serverSettings);
      ['to', 'cc', 'bcc'].forEach(field => renderRecipientChips(field));
      setupResizers();
      loadContacts(false, false).catch(() => {});
      refreshSavedCount(false);
      loadMailboxPreferences();
      updateQueueStat();
      showAccountSwitchedNotice();
      $('#startMailboxFromFile').addEventListener('click', () => startApplicationMailbox().catch(handleError));
      initialiseApplicationStartup().catch(handleError);
      installMailboxBackgroundHandlers();
      if (new URLSearchParams(location.search).get('google_oauth') === 'success') {
        const cleanUrl = new URL(location.href);
        cleanUrl.searchParams.delete('google_oauth');
        history.replaceState({}, '', cleanUrl.pathname + cleanUrl.search + cleanUrl.hash);
        setTimeout(async () => {
          toast('Google account connected.', 'success');
          await openSettings();
        }, 250);
      }
      /* PSE_MAILBOX_BACKGROUND_START */
      function installMailboxBackgroundHandlers() {
        const recordActivity = () => {
          state.lastActivity = Date.now();
        };
        ['pointerdown', 'keydown', 'touchstart', 'wheel'].forEach(eventName => {
          document.addEventListener(eventName, recordActivity, {passive: true});
        });
        window.addEventListener('offline', () => {
          pausePrefetch('network', true);
        });
        window.addEventListener('online', () => {
          if (!state.mailboxStarted) return;
          resumePrefetch('network');
          scheduleVisibleMessagePrefetch(state.prefetchGeneration);
        });
        const networkConnection = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
        networkConnection?.addEventListener?.('change', () => {
          if (!state.mailboxStarted) return;
          if (prefetchConnectionAllowsBackground()) {
            resumePrefetch('network-policy');
            scheduleVisibleMessagePrefetch(state.prefetchGeneration);
          } else {
            pausePrefetch('network-policy', true);
          }
        });
        if (navigator.onLine === false) pausePrefetch('network');
        if (!prefetchConnectionAllowsBackground()) pausePrefetch('network-policy');
        window.addEventListener('beforeunload', () => {
          saveComposeBeforeBrowserClose();
        });
        window.addEventListener('pagehide', () => {
          saveComposeBeforeBrowserClose();
          interruptPrefetchRequests();
          if (!state.mailboxStarted) return;
          fetch('?ajax=handle_queue', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'X-PSE-CSRF': csrf
            },
            body: '{}',
            keepalive: true
          }).catch(() => {});
        });
        setInterval(() => {
          if (state.mailboxStarted) flushActionQueue(true);
        }, 60000);
        setInterval(() => {
          if (state.mailboxStarted) pollFolderStatus();
        }, mailboxCheckIntervalMs());
        setInterval(refreshLastSyncStatus, 300000);
        document.addEventListener('visibilitychange', () => {
          if (state.mailboxStarted && !document.hidden) {
            refreshLastSyncStatus();
            pollFolderStatus();
          }
        });
        document.addEventListener('hidden.bs.modal', () => {
          if (!state.mailboxStarted && !$('.modal.show')) scheduleApplicationUpdateStartup();
        });
      }
      /* PSE_MAILBOX_BACKGROUND_END */
    })();
  </script>
<?php endif; ?>
  <script>
    (() => {
      'use strict';

      const pwa = {
        deferredPrompt: null,
        installed: false,
        runningStandalone: false,
        installKnown: false,
        relatedAppsSupported: 'getInstalledRelatedApps' in navigator,
        relatedAppsChecked: false,
        secure: window.isSecureContext,
        localHint: false,
        registration: null,
        installedEvidence: 'none'
      };
      const pwaHintKey = 'pse_pwa_installed_hint_v1';
      const pwaAppIconUrl = <?= json_encode((string)$pseIconHref, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?>;
      const pwaAppTitle = <?= json_encode((string)($pseUiSettings['app_title'] ?? 'PSE Email'), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?>;
      const pwaWorkerUrl = new URL('?pwa=sw', location.href).href;
      const pwaScopeUrl = new URL('./', location.href).href;

      function pwaIsStandalone() {
        const modes = ['standalone', 'fullscreen', 'minimal-ui', 'window-controls-overlay'];
        return modes.some(mode => window.matchMedia(`(display-mode: ${mode})`).matches) || navigator.standalone === true;
      }

      function pwaIsIos() {
        return /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
      }

      function pwaIsSafari() {
        return /^((?!chrome|android|crios|fxios|edgios).)*safari/i.test(navigator.userAgent);
      }

      function pwaReadHint() {
        try {
          return localStorage.getItem(pwaHintKey) === '1';
        } catch (error) {
          return false;
        }
      }

      function pwaWriteHint(installed) {
        try {
          if (installed) localStorage.setItem(pwaHintKey, '1');
          else localStorage.removeItem(pwaHintKey);
        } catch (error) {}
      }

      function pwaState() {
        if (pwa.runningStandalone) {
          return {
            code: 'running',
            label: 'Running as installed app',
            detail: 'PSE is currently running in standalone app mode.',
            dot: 'installed'
          };
        }
        if (pwa.installed) {
          if (pwa.installedEvidence === 'hint') {
            return {
              code: 'installed-hint',
              label: 'Installation previously detected',
              detail: 'PSE was previously installed in this browser profile, but this browser cannot directly verify that it is still installed.',
              dot: 'installed'
            };
          }
          return {
            code: 'installed',
            label: 'Installed on this device',
            detail: 'PSE appears to already be installed. Open it from your Home Screen or app launcher.',
            dot: 'installed'
          };
        }
        if (!pwa.secure) {
          return {
            code: 'insecure',
            label: 'HTTPS required for installation',
            detail: 'Open this same PSE URL over HTTPS before installing it as an app.',
            dot: 'warning'
          };
        }
        if (pwa.deferredPrompt) {
          return {
            code: 'ready',
            label: 'Ready to install',
            detail: 'Your browser can install PSE directly from this page.',
            dot: 'ready'
          };
        }
        if (pwaIsIos()) {
          return {
            code: 'manual-ios',
            label: 'Install from the browser Share menu',
            detail: 'On iPhone/iPad, use Share → Add to Home Screen. Browser support differs by iOS version and browser.',
            dot: 'ready'
          };
        }
        return {
          code: 'manual',
          label: pwa.installKnown ? 'Installation not currently offered' : 'Installation status unavailable',
          detail: 'Use your browser menu and choose Install app or Add to Home Screen if available.',
          dot: 'warning'
        };
      }

      function pwaSetButton(button, state) {
        if (!button) return;
        const icon = button.querySelector('i');
        const text = button.querySelector('span');
        button.classList.remove('pse-pwa-ready');
        button.disabled = false;

        if (state.code === 'running') {
          button.classList.add('d-none');
          return;
        }

        button.classList.remove('d-none');
        if (state.code === 'installed' || state.code === 'installed-hint') {
          if (icon) icon.className = 'fa-solid fa-circle-check' + (button.id === 'pwaSettingsInstallButton' ? ' me-1' : '');
          if (text) text.textContent = 'Installed';
          button.disabled = false;
          button.title = 'PSE is already installed';
          return;
        }

        if (icon) icon.className = 'fa-solid fa-download' + (button.id === 'pwaSettingsInstallButton' || button.id === 'pwaAuthInstallButton' ? ' me-1' : '');
        if (text) text.textContent = button.id === 'pwaInstallButton' ? 'Install' : 'Install';
        if (state.code === 'ready') button.classList.add('pse-pwa-ready');
        button.title = state.label;
      }

      function pwaRender() {
        pwa.runningStandalone = pwaIsStandalone();
        if (pwa.runningStandalone) {
          pwa.installed = true;
          pwa.installedEvidence = 'standalone';
          pwa.installKnown = true;
          pwaWriteHint(true);
        }
        const state = pwaState();
        pwaSetButton(document.getElementById('pwaInstallButton'), state);
        pwaSetButton(document.getElementById('pwaAuthInstallButton'), state);
        pwaSetButton(document.getElementById('pwaSettingsInstallButton'), state);

        const status = document.getElementById('pwaSettingsStatus');
        const detail = document.getElementById('pwaSettingsDetail');
        const dot = document.getElementById('pwaSettingsStatusDot');
        if (status) status.textContent = state.label;
        if (detail) detail.textContent = state.detail + ' Private email content is not cached by the PWA service worker.';
        if (dot) {
          dot.className = 'pse-pwa-status-dot' + (state.dot ? ' ' + state.dot : '');
        }
      }

      function pwaDialogHtml(state) {
        let instructions = '';
        if (state.code === 'manual-ios') {
          instructions = `<div class="pse-pwa-instructions"><strong><i class="fa-solid fa-arrow-up-from-bracket me-1"></i>iPhone / iPad</strong><br>Open the browser <strong>Share</strong> menu, choose <strong>Add to Home Screen</strong>, then confirm <strong>Add</strong>.</div>`;
        } else if (state.code === 'manual') {
          instructions = `<div class="pse-pwa-instructions"><strong><i class="fa-solid fa-ellipsis-vertical me-1"></i>Manual installation</strong><br>Open your browser menu and choose <strong>Install app</strong>, <strong>Install PSE</strong>, or <strong>Add to Home Screen</strong>. The exact wording depends on the browser.</div>`;
        } else if (state.code === 'insecure') {
          instructions = `<div class="pse-pwa-instructions"><strong><i class="fa-solid fa-lock me-1"></i>Secure connection required</strong><br>PWA installation requires HTTPS (except localhost development). Reopen this PSE installation using its HTTPS URL.</div>`;
        } else if (state.code === 'installed' || state.code === 'installed-hint') {
          instructions = `<div class="pse-pwa-instructions"><strong><i class="fa-solid fa-house me-1"></i>${state.code === 'installed-hint' ? 'Previously installed' : 'Already installed'}</strong><br>${state.code === 'installed-hint' ? 'Direct verification is unavailable in this browser. If you removed PSE, use the browser Install app command when it becomes available.' : 'Launch PSE from your Home Screen, desktop, Start menu, Dock, or application launcher.'}</div>`;
        } else if (state.code === 'running') {
          instructions = `<div class="pse-pwa-instructions"><strong><i class="fa-solid fa-circle-check me-1"></i>Installed mode active</strong><br>You are already using the standalone PSE app.</div>`;
        }

        return `
          <div class="pse-pwa-dialog">
            <div class="pse-pwa-dialog-hero">
              <img class="pse-pwa-dialog-logo" src="${escapePwaHtml(pwaAppIconUrl)}" alt="PSE">
              <div>
                <div class="pse-pwa-dialog-title">Install ${escapePwaHtml(pwaAppTitle || 'PSE Email')}</div>
                <div class="pse-pwa-dialog-status"><span class="pse-pwa-status-dot ${escapePwaClass(state.dot)}"></span>${escapePwaHtml(state.label)}</div>
              </div>
            </div>
            <div class="pse-pwa-benefits">
              <div class="pse-pwa-benefit"><span class="pse-pwa-benefit-icon"><i class="fa-solid fa-window-maximize"></i></span><div><strong>Dedicated app window</strong><span>Launch PSE without normal browser chrome.</span></div></div>
              <div class="pse-pwa-benefit"><span class="pse-pwa-benefit-icon"><i class="fa-solid fa-mobile-screen-button"></i></span><div><strong>Home Screen & app launcher</strong><span>Open it like your other installed applications.</span></div></div>
              <div class="pse-pwa-benefit"><span class="pse-pwa-benefit-icon"><i class="fa-solid fa-shield-halved"></i></span><div><strong>Private by design</strong><span>The service worker does not cache mailbox or authenticated email responses.</span></div></div>
            </div>
            ${instructions}
          </div>`;
      }

      function escapePwaHtml(value) {
        return String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[char]);
      }

      function escapePwaClass(value) {
        return /^[a-z-]+$/.test(String(value || '')) ? String(value) : '';
      }

      async function pwaShowInstall() {
        const state = pwaState();
        const canPrompt = state.code === 'ready' && pwa.deferredPrompt;
        const result = await Swal.fire({
          html: pwaDialogHtml(state),
          showCancelButton: true,
          showConfirmButton: canPrompt,
          confirmButtonText: '<i class="fa-solid fa-download me-2"></i>Install PSE',
          cancelButtonText: state.code === 'running' || state.code === 'installed' || state.code === 'installed-hint' ? 'Close' : 'Not now',
          buttonsStyling: true,
          customClass: {popup: 'pse-pwa-swal-popup'},
          width: 520,
          focusConfirm: false
        });

        if (!result.isConfirmed || !canPrompt) return;
        const prompt = pwa.deferredPrompt;
        pwa.deferredPrompt = null;
        pwaRender();
        try {
          await prompt.prompt();
          const choice = await prompt.userChoice;
          if (choice && choice.outcome === 'accepted') {
            pwaWriteHint(true);
          }
        } catch (error) {
          console.warn('PWA installation prompt failed.', error);
        }
        window.setTimeout(pwaDetectInstalled, 500);
      }

      async function pwaDetectInstalled() {
        pwa.runningStandalone = pwaIsStandalone();
        pwa.localHint = pwaReadHint();
        if (pwa.runningStandalone) {
          pwa.installed = true;
          pwa.installedEvidence = 'standalone';
          pwa.installKnown = true;
          pwaWriteHint(true);
          pwaRender();
          return;
        }

        if (pwa.relatedAppsSupported) {
          try {
            const apps = await navigator.getInstalledRelatedApps();
            pwa.relatedAppsChecked = true;
            pwa.installKnown = true;
            const webApps = Array.isArray(apps) ? apps.filter(app => String(app.platform || '').toLowerCase() === 'webapp') : [];
            if (webApps.length > 0) {
              pwa.installed = true;
              pwa.installedEvidence = 'related';
              pwaWriteHint(true);
            } else if (!pwa.deferredPrompt) {
              pwa.installed = pwa.localHint;
              pwa.installedEvidence = pwa.localHint ? 'hint' : 'none';
            }
          } catch (error) {
            pwa.relatedAppsChecked = true;
            pwa.installed = pwa.localHint;
            pwa.installedEvidence = pwa.localHint ? 'hint' : 'none';
          }
        } else {
          pwa.installed = pwa.localHint;
          pwa.installedEvidence = pwa.localHint ? 'hint' : 'none';
        }
        pwaRender();
      }

      async function pwaRegisterServiceWorker() {
        if (!('serviceWorker' in navigator) || !window.isSecureContext) return;
        try {
          pwa.registration = await navigator.serviceWorker.register(pwaWorkerUrl, {scope: pwaScopeUrl});
          pwa.registration.update().catch(() => {});
        } catch (error) {
          console.warn('PSE service worker registration failed.', error);
        }
      }

      window.addEventListener('beforeinstallprompt', event => {
        event.preventDefault();
        pwa.deferredPrompt = event;
        pwa.installKnown = true;
        pwa.installed = false;
        pwa.installedEvidence = 'none';
        pwaWriteHint(false);
        pwaRender();
      });

      window.addEventListener('appinstalled', () => {
        pwa.deferredPrompt = null;
        pwa.installed = true;
        pwa.installedEvidence = 'event';
        pwa.installKnown = true;
        pwaWriteHint(true);
        pwaRender();
        if (typeof Swal !== 'undefined') {
          Swal.fire({
            icon: 'success',
            title: 'PSE installed',
            text: 'PSE Email is now available from your app launcher or Home Screen.',
            timer: 2600,
            showConfirmButton: false
          });
        }
      });

      ['pwaInstallButton', 'pwaAuthInstallButton', 'pwaSettingsInstallButton'].forEach(id => {
        document.getElementById(id)?.addEventListener('click', pwaShowInstall);
      });

      ['standalone', 'fullscreen', 'minimal-ui', 'window-controls-overlay'].forEach(mode => {
        const query = window.matchMedia(`(display-mode: ${mode})`);
        query.addEventListener?.('change', pwaDetectInstalled);
      });

      pwaRegisterServiceWorker();
      pwaDetectInstalled();
      window.setTimeout(pwaRender, 1200);
    })();
  </script>
</body>
</html>
